(7685998, 1258491, 86447, '<td valign="top">Looks like a TVSometime image.   I love it!</td>', 'Looks like a TVSometime image.   I love it!', '2021-02-03 11:22:42.000000', NULL, 1),
(7685999, 1258416, 86447, '<td valign="top">LOL @ your title.  Yeah... I''m that old.  :D</td>', 'LOL @ your title.  Yeah... I''m that old.  :D', '2021-02-03 11:23:10.000000', NULL, 1),
(7686002, 1258533, 4008, '<td valign="top">I see two images of this same pier in this challenge. The perspective of this one is better in my view. It makes better use of the vanishing point and the tilt angle makes it more dynamic.</td>', 'I see two images of this same pier in this challenge. The perspective of this one is better in my view. It makes better use of the vanishing point and the tilt angle makes it more dynamic.', '2021-02-03 13:13:27.000000', NULL, 1),
(7686003, 1258647, 4008, '<td valign="top">Is see two images of this same pier in this challenge. In my view the other is better as result of its low perspective and view angle. It makes it more dynamic.</td>', 'Is see two images of this same pier in this challenge. In my view the other is better as result of its low perspective and view angle. It makes it more dynamic.', '2021-02-03 13:14:50.000000', NULL, 1),
(7686004, 1258635, 4008, '<td valign="top">I don''t understand why this was entered in this challenge. I see some parallel lines but those are not working towards a vanishing point in terms of composition.</td>', 'I don''t understand why this was entered in this challenge. I see some parallel lines but those are not working towards a vanishing point in terms of composition.', '2021-02-03 13:20:06.000000', NULL, 1),
