(7686029, 1258250, 4008, '<td valign="top">Strong image, even though, or maybe because, the parallel lines towards the vanishing point are virtual. Top 3.</td>', 'Strong image, even though, or maybe because, the parallel lines towards the vanishing point are virtual. Top 3.', '2021-02-04 04:44:40.000000', NULL, 1),
(7686030, 1258654, 4008, '<td valign="top">Strong image. I like it how the movement adds to the direction of the lines. Top 3.</td>', 'Strong image. I like it how the movement adds to the direction of the lines. Top 3.', '2021-02-04 04:44:47.000000', NULL, 1),
(7686031, 1258551, 4008, '<td valign="top">I had an escalator image in my options for this challenge but submitted another. I like the colours, reflections and symmetry in your image. A lower standpoint might have made it even stronger.</td>', 'I had an escalator image in my options for this challenge but submitted another. I like the colours, reflections and symmetry in your image. A lower standpoint might have made it even stronger.', '2021-02-04 04:46:40.000000', NULL, 1),
(7686032, 1258640, 4008, '<td valign="top">Even though the vanishing point itself is hidden, the image still works. Love the clouds and waves and the the rainbow.</td>', 'Even though the vanishing point itself is hidden, the image still works. Love the clouds and waves and the the rainbow.', '2021-02-04 04:47:43.000000', NULL, 1),
(7686033, 1258416, 4008, '<td valign="top">The idea is great, very creative and different, but it still results in an image that leaves me cold.</td>', 'The idea is great, very creative and different, but it still results in an image that leaves me cold.', '2021-02-04 04:48:44.000000', NULL, 1),
(7686034, 1258257, 4008, '<td valign="top">Extremely long lines with perfect vanishing point. The cyclist looking into the distance  and the sign add a good point of interest, like the pedestrian further down. Strong.</td>', 'Extremely long lines with perfect vanishing point. The cyclist looking into the distance  and the sign add a good point of interest, like the pedestrian further down. Strong.', '2021-02-04 04:49:57.000000', NULL, 1),
(7686035, 1258642, 4008, '<td valign="top">The low sun adds something special to this landscape.</td>', 'The low sun adds something special to this landscape.', '2021-02-04 04:50:23.000000', NULL, 1),
(7686103, 1258640, 67145, '<td valign="top">this is absolutely stunning .. rainbows come and go so quickly .. how incredibly awesome that you were in the right place at the right time .. <br/>this has blue written all over it to me ..  but there are some other pretty cool images in the challenge too .. spose it comes down to personal choice .. and this is mine . !! .. :)</td>', 'this is absolutely stunning .. rainbows come and go so quickly .. how incredibly awesome that you were in the right place at the right time .. this has blue written all over it to me ..  but there are some other pretty cool images in the challenge too .. spose it comes down to personal choice .. and this is mine . !! .. :)', '2021-02-05 01:14:33.000000', NULL, 1),
(7686104, 1258246, 67145, '<td valign="top">this is awesome .. loving the feeling of movement .. and the light .. <br/>makes me wonder how you got this shot .. either you are a train driver or standing at the back of the train .. either are possible .. :)</td>', 'this is awesome .. loving the feeling of movement .. and the light .. makes me wonder how you got this shot .. either you are a train driver or standing at the back of the train .. either are possible .. :)', '2021-02-05 01:18:11.000000', NULL, 1),
